{"operation":"run_python","code":"from collections import deque

def min_knight_moves():
    board = 8
    start = (0, 0)
    end = (7, 7)

    visited = set()
    queue = deque([(start, 0)])
    visited.add(start)

    moves = [
        (1, 2), (2, 1), (-1, 2), (-2, 1),
        (1, -2), (2, -1), (-1, -2), (-2, -1)
    ]

    while queue:
        (r, c), dist = queue.popleft()
        if (r, c) == end:
            return dist
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < board and 0 <= nc < board and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append(((nr, nc), dist + 1))
    return -1

print(min_knight_moves())"}

{"operation":"run_python","code":"from collections import deque

def solve():
    target = tuple(range(1, 11))
    start = (3, 8, 5, 1, 7, 10, 2, 6, 9, 4)

    if start == target:
        return 0

    queue = deque([(start, 0)])
    visited = {start}

    while queue:
        curr, dist = queue.popleft()
        n = len(curr)

        for i in range(n):
            for j in range(i + 1, n):
                # reverse curr[i:j+1]
                new_curr = list(curr[:i]) + list(reversed(curr[i:j+1])) + list(curr[j+1:])
                new_tuple = tuple(new_curr)

                if new_tuple == target:
                    return dist + 1

                if new_tuple not in visited:
                    visited.add(new_tuple)
                    queue.append((new_tuple, dist + 1))

print(solve())
"}

